INSERT INTO platillos_ingredientes (id_platillo, id_ingrediente, cantidad, unidad, is_synthetic) SELECT p.id_platillo, i.id_ingrediente, v.g, 'g', true FROM platillos p JOIN (VALUES ('Pollo', 120), ('Aguacate', 60), ('Lechuga', 60), ('Tomate', 60), ('Pepino', 40), ('Aceite de oliva', 5), ('Limón', 10)) AS v(nombre, g) ON true JOIN ingredientes i ON i.nombre_ingrediente = v.nombre WHERE p.nombre_platillo = 'Ensalada de pollo con aguacate';
