-- Control: cada platillo sintético debe quedar con todos sus ingredientes enlazados
DO $$
DECLARE faltan INTEGER;
BEGIN
  SELECT COUNT(*) INTO faltan FROM platillos p
  WHERE p.is_synthetic AND NOT EXISTS (SELECT 1 FROM platillos_ingredientes pi WHERE pi.id_platillo = p.id_platillo);
  IF faltan > 0 THEN RAISE EXCEPTION 'Hay % platillos sin ingredientes', faltan; END IF;
END $$;

